# also try 8-neighborhood
def solve8(g):
    R,C=len(g),len(g[0])
    out=[[0]*C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            iso=True
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    if dr==dc==0:continue
                    rr,cc=r+dr,c+dc
                    if 0<=rr<R and 0<=cc<C and g[rr][cc]==g[r][c]:
                        iso=False
            out[r][c]=0 if iso else 1
    return out
